Translate("zhCN", "dun-morogh", {
	title = "丹莫罗",
	sections = {
		{
			title = "概述",
			text = [=[丹莫罗是卡兹莫丹西部一片冰雪与岩石的土地，是{link:dwarves}矮人{/link}的古老故乡。它的山峰是{link:eastern-kingdoms}东部王国{/link}最高的，在其中最雄伟的一座山中坐落着{link:ironforge}铁炉堡{/link}，{link:kingdom-of-ironforge}铁炉堡王国{/link}的首都。{link:gnomes}侏儒{/link}也曾在这里生活，住在西部丘陵之下的{link:gnomeregan}诺莫瑞根{/link}城中。两座城市之间是冰封的湖泊、松林和一条穿过雪原的漫长道路。这是一片严酷的土地，它的人民为之自豪。]=],
		},
		{
			title = "起源",
			text = [=[{link:dwarves}矮人{/link}说，他们在远古时代由这些山中的岩石塑造而成，{link:ironforge}铁炉堡{/link}是他们最古老的家园。很久以前，所有矮人都由一位至高王从这里统治。那位国王死后，铜须、蛮锤和{link:dark-iron-dwarves}黑铁{/link}三个氏族为争夺他的王位而开战，铜须氏族守住了这座大山。{link:gnomes}侏儒{/link}成为矮人的邻居和朋友，他们在西部山麓建起了{link:gnomeregan}诺莫瑞根{/link}。没有任何编年史记载这两座城市建立的年份。]=],
		},
		{
			title = "当今",
			text = [=[丹莫罗如今比人们记忆中的任何时候都更不安全。国王的大部分军队远在他乡，为{link:alliance}联盟{/link}效力，留下来的山地巡逻员寥寥无几。{link:troggs}石腭怪{/link}从地底深处涌了出来，如今占据着{link:coldridge-valley}寒脊{/link}山小径和{link:gol-bolar-quarry}古博拉采掘场{/link}的矿坑。{link:frostmane-trolls}霜鬃巨魔{/link}占据着西部的洞穴和山岭。{link:gnomeregan}诺莫瑞根{/link}已经失陷，它中毒的人民在城门前游荡。雪人占满了{link:the-grizzled-den}灰色洞穴{/link}。最令人不安的是，有人在东部看到了{link:dark-iron-dwarves}黑铁氏族{/link}的间谍，他们携带着通往{link:ironforge}铁炉堡{/link}地下的隧道地图。]=],
		},
		{
			title = "居民",
			text = [=[• {b}{link:ironforge}铁炉堡{/link}的{link:dwarves}矮人{/link}。{/b}矿工、酿酒师、山羊饲养者和山地巡逻员，他们生活在{link:kharanos}卡拉诺斯{/link}、{link:brewnall-village}烈酒村{/link}和{link:razorfen-downs}高地{/link}上孤零零的营地中。
• {b}{link:gnomeregan}诺莫瑞根{/link}的{link:gnomes}侏儒{/link}。{/b}他们沦陷之城的幸存者在铁炉堡栖身，其中一些人在卡拉诺斯工作，试图挽回已经造成的伤害。
• {b}{link:frostmane-trolls}霜鬃巨魔{/link}。{/b}他们占据着西部的洞穴和山岭，与矮人争夺这片雪原。
• {b}{link:troggs}石腭怪{/link}。{/b}石腭怪从地下涌出，如今在矮人挖掘的任何地方发动袭击。
• {b}雪人与野兽。{/b}雪人、熊、野猪和雪豹在山丘间游荡，其中一些变得过于大胆，也过于庞大。
• {b}{link:dark-iron-dwarves}黑铁矮人{/link}。{/b}他们中的一伙人占据着东部的{link:ironband-s-compound}铁环营地{/link}，观望等待。]=],
		},
		{
			title = "历史",
			text = [=[• {b}三锤之战。{/b}在三个氏族的战争中，铜须氏族守住了{link:ironforge}铁炉堡{/link}，并驱逐了他们的对手。一份保存在城市地下的条约记载着，蛮锤氏族签署了和约，而{link:dark-iron-dwarves}黑铁氏族{/link}没有。
• {b}{link:second-war}第二次战争{/link}。{/b}当{link:horde}部落{/link}席卷卡兹莫丹时，铁炉堡本身坚守住了。{link:dwarves}矮人{/link}加入了{link:alliance}洛丹伦联盟{/link}，与{link:humans}人类{/link}并肩作战，直到部落被击溃。
• {b}{link:gnomeregan}诺莫瑞根{/link}的陷落。{/b}{link:troggs}石腭怪{/link}在{link:gnomes}侏儒{/link}之城的地下崛起。侏儒奋力将它们驱逐，但他们使用的武器毒害了城市和许多自己人。幸存者逃往了铁炉堡。
• {b}当今。{/b}如今矮人同时面对着石腭怪、{link:trolls}巨魔{/link}和黑铁矮人，而他们的一半力量远在他乡征战。]=],
		},
		{
			title = "山中传说",
			text = [=[• {link:kharanos}卡拉诺斯{/link}的{link:farmer-ray}雷{/link}酒家族和{link:brewnall-village}烈酒村{/link}的麦酒家族是相互竞争的酿酒世家。双方都认为对方的麦酒只配给野猪喝。
• {link:frostmane-trolls}霜鬃巨魔{/link}在{link:iceflow-lake}涌冰湖{/link}上方的山岭上种植一种名叫微光草的苍白草药，并在仪式中使用它。{link:dwarves}矮人{/link}为它找到了更好的用途：黑啤酒。
• {link:ironforge}铁炉堡{/link}的山地巡逻员把自己的名字刻在步枪的枪托上，这样就能让冰雪说出它带走了谁。
• 铁炉堡的盗贼们窃窃私语，说国王的装甲蒸汽坦克沿着一条奇怪的绕远路线从{link:gol-bolar-quarry}古博拉采掘场{/link}运送矿石和宝石，应该有人替他分担一点。]=],
		},
	},
})

