			title = "概述",
			text = [=[寒脊山谷是{link:dun-morogh}丹莫罗{/link}西南部一处隐蔽的{link:stranglethorn-vale}山谷{/link}，四面被群山环绕。{link:ironforge}铁炉堡{/link}的新守卫者来到这里，在安威玛尔学习他们的本领。山谷已经失去了它的宁静。{link:troggs}石腭怪{/link}攻占了西边的营地，并在冰冻湖泊旁的山丘上成群出没。{link:frostmane-trolls}霜鬃巨魔{/link}占据着南边的一个洞穴。唯一的出路是穿过寒脊山小径的隧道，如今那里挤满了石腭怪，一名山地巡逻员在隧道口值守。]=],
		},
	},
})

Translate("zhCN", "anvilmar", {
