	sections = {
		{
			title = "概述",
			text = [=[钢架补给站就在{link:kharanos}卡拉诺斯{/link}东北方。这里是山中最出色的攻城器械技师{link:beldin-steelgrill}贝尔丁·钢架{/link}的工坊，也是攻城旅驾驶员们常来的地方。他们的装甲蒸汽坦克有着诸如“喷汽号”和“犁魔号”之类的名字，驾驶员们夸耀它们，就像其他{link:dwarves}矮人{/link}夸耀山羊一样。补给站能听到道路上发生的许多事，正是一名山地巡逻员在这里的报告，让人们首次注意到{link:gol-bolar-quarry}古博拉{/link}上方一堆奇怪的篝火。]=],
		},
	},
