	sections = {
		{
			title = "概述",
			text = [=[寒风峡谷位于{link:dun-morogh}丹莫罗{/link}西部，在{link:kharanos}卡拉诺斯{/link}和{link:gnomeregan}诺莫瑞根{/link}的丘陵之间。它的东段人来人往，因为从{link:coldridge-valley}寒脊{/link}山小径而来的道路穿过这里。很少有人愿意走进它更僻静的角落。在那里，一只名叫老冰须的巨大雪人占据着一个洞穴，他曾把捕{link:orcs}兽人{/link}图德拉·马克格拉恩的整个肉食储藏柜都搬走了，后者如今拖着一条伤腿、饿着肚子在附近扎营。]=],
		},
	},
})

Translate("zhCN", "brewnall-village", {
