	sections = {
		{
			title = "概述",
			text = [=[烈酒村坐落在{link:iceflow-lake}涌冰湖{/link}西岸。这里是麦酒家族的家园，这些酿酒师大胆试验，有时也会失败。他们的恒光酒烈得连攻城驾驶员都把它倒进锅炉里。麦酒家族对{link:kharanos}卡拉诺斯{/link}的{link:farmer-ray}雷{/link}酒家族毫无好感，也不介意在对手的地窖里搞点小恶作剧。渔夫们在他们旁边的湖上劳作，{link:frostmane-trolls}霜鬃巨魔{/link}则在西南方虎视眈眈。]=],
