	},
})

Translate("zhCN", "iceflow-lake", {
	title = "涌冰湖",
	sections = {
		{
			title = "概述",
			text = [=[涌冰湖横亘在{link:dun-morogh}丹莫罗{/link}北部，位于{link:ironforge}铁炉堡{/link}以西，一年中大部分时间都被冰封。一条冰河从{link:kharanos}卡拉诺斯{/link}以北的桥下流向湖中。狼群在湖中央的岛上猎食。{link:brewnall-village}烈酒村{/link}的渔夫们在冰面上凿洞，守着钓线一等就是好几天，他们咒骂那些偷走他们少得可怜的渔获的雪人。]=],
		},
	},
})

Translate("zhCN", "frostmane-hold", {
