Translate("zhCN", "shimmer-ridge", {
	title = "闪光岭",
	sections = {
		{
			title = "概述",
			text = [=[闪光岭是{link:dun-morogh}丹莫罗{/link}北部的一片高丘，靠近{link:iceflow-lake}涌冰湖{/link}，位于{link:ironforge}铁炉堡{/link}大门以西。{link:frostmane-trolls}霜鬃巨魔{/link}在山岭上设有营地，营地之间以一座桥相连，他们的先知在那里照料着一篮篮微光草。这种草药在他们的仪式中有某种作用。对{link:brewnall-village}烈酒村{/link}的酿酒师来说，它另有用途，他们会重{link:ginro-hearthkindle}金{/link}酬谢任何愿意爬上山岭去偷草的人。]=],
		},
	},
})

Translate("zhCN", "gates-of-gnomeregan", {
