	sections = {
		{
			title = "概述",
			text = [=[在{link:brewnall-village}烈酒村{/link}以北，{link:dun-morogh}丹莫罗{/link}西部的丘陵一直延伸到{link:gnomeregan}诺莫瑞根{/link}的大门。这里曾是一片满是{link:gnomes}侏儒{/link}机械和村落的繁忙之地。如今，水泵和过滤器破损失修，留下来的侏儒中了毒，病弱而充满敌意，在他们未能拯救的城市门前游荡。一名居心叵测的{link:dwarves}矮人{/link}间谍乔装藏身于他们之中。逃出来的侏儒说，他们族人的珍贵记录至今仍埋在这里的雪中。]=],
		},
	},
})

Translate("zhCN", "gol-bolar-quarry", {
	title = "古博拉采掘场",
	aliases = { "古博拉" },
	sections = {
		{
			title = "概述",
			text = [=[古博拉采掘场是{link:dun-morogh}丹莫罗{/link}东部的一个巨大露天矿坑，国王的矿工们在这里开采矿石和石料。当他们挖得很深时，{link:troggs}石腭怪{/link}从岩石中涌出，砸毁了机器，将矿工赶出了矿坑。如今工头大发{link:farmer-ray}雷{/link}霆，一位{link:ironforge}铁炉堡{/link}议员悬赏石腭怪的首级，而采石场主管则希望没有人发现石腭怪偷走了他的炸药。在上方的冻土岭，一个蛮锤族的陌生人注视着这一切。]=],
		},
	},
})

Translate("zhCN", "amberstill-ranch", {
