Translate("zhCN", "misty-pine-refuge", {
	title = "雾松避难所",
	sections = {
		{
			title = "概述",
			text = [=[雾松避难所是{link:dun-morogh}丹莫罗{/link}北部丘陵中一座孤零零的房子，位于{link:ironforge}铁炉堡{/link}大门以东。{link:argent-dawn}银色黎明{/link}的{link:father-gavin}伽文神父{/link}修缮了它，为任何被严寒困住的旅人点燃炉火。它周围的山已经变得危险。一场从山顶滑落的岩崩惊动了冰之灵，其中最大的一个似乎走到哪里，就把风暴和新的山崩带到哪里。]=],
