		},
	},
})

Translate("zhCN", "ironband-s-compound", {
	title = "铁环营地",
	sections = {
		{
			title = "概述",
			text = [=[铁环营地是{link:helm-s-bed-lake}盔枕湖{/link}以南的一座房屋和院落，位于{link:dun-morogh}丹莫罗{/link}东部。它的{link:dwarves}矮人{/link}主人已经离开了。如今{link:dark-iron-dwarves}黑铁矮人{/link}占据着这里，由一名叫贝尔德的队长率领，他们攻击任何靠近的人。蛮锤族的{link:earthseer-farsen}大地先知法森{/link}相信他们不仅仅是劫掠者。从他们的尸体上取得的地图显示，有一些隧道在地下延伸得很远，并在{link:ironforge}铁炉堡{/link}下方交汇。]=],
