Translate("zhCN", "frostmane-trolls", {
	title = "霜鬃巨魔",
	aliases = { "霜鬃", "霜鬃部族" },
	sections = {
		{
			title = "概述",
			text = [=[霜鬃是一个生活在{link:dun-morogh}丹莫罗{/link}雪原中的{link:trolls}巨魔{/link}部族。他们凶猛而诡秘，与{link:dwarves}矮人{/link}争夺这片山脉。没有任何编年史记载他们最初何时来到这里。]=],
		},
		{
			title = "他们的领地",
			text = [=[他们最大的据点是{link:frostmane-hold}霜鬃巨魔要塞{/link}，那是{link:brewnall-village}烈酒村{/link}西南的一个洞穴。他们还在{link:shimmer-ridge}闪光岭{/link}上设有营地，并在{link:coldridge-valley}寒脊山谷{/link}南部占据着一个洞穴，部族的幼崽住在那里。他们的战士是猎头者和雪地行者。他们的先知和暗影法师施展着自己的魔法，并为仪式采集微光草。]=],
		},
		{
			title = "当今",
			text = [=[{link:ironforge}铁炉堡{/link}{link:shadow-council}议会{/link}忙于应付{link:troggs}石腭怪{/link}，宁愿完全不去考虑{link:trolls}巨魔{/link}。白须家族的两兄弟被派去查明威胁到底有多大。{link:grelin-whitebeard}格瑞林{/link}判断{link:coldridge-valley}寒脊{/link}的巨魔为数不多。森尼尔却发现{link:frostmane-hold}霜鬃巨魔要塞{/link}里满是巨魔。两份报告之间的分歧，就是{link:dwarves}矮人{/link}能够承受忽视多少威胁的问题。在寒脊，一个名叫{link:grik-nir-the-cold}冷酷的格瑞克尼尔{/link}的巨魔从矮人那里偷走的不只是一本日志：他让他们明白，霜鬃巨魔正在注视着他们。]=],
		},
	},
})

Translate("zhCN", "gnomeregan-exiles", {
	title = "诺莫瑞根流亡者",
	aliases = { "诺莫瑞根的流亡者" },
	sections = {
		{
			title = "概述",
			text = [=[诺莫瑞根流亡者是在他们的城市陷落后幸存下来的{link:gnomes}侏儒{/link}。他们是一个没有家园的民族。他们大多住在{link:ironforge}铁炉堡{/link}，国王{link:magni-bronzebeard}麦格尼·铜须{/link}在{link:tinker-town}侏儒区{/link}给了他们一席之地，但他们也散布在{link:dun-morogh}丹莫罗{/link}各地及更远的地方。]=],
		},
		{
			title = "陷落之后",
			text = [=[{link:troggs}石腭怪{/link}从{link:gnomeregan}诺莫瑞根{/link}地下涌出，{link:gnomes}侏儒{/link}用他们自己制造的一件武器将其击退。结果却酿成了可怕的灾难。城市被毒害，许多居民变成了病弱痴呆的麻风侏儒，至今仍在城门前游荡。其余的人带着能带走的一切逃进了雪原。一些人在路上被{link:trolls}巨魔{/link}夺走了所有的东西。另一些人则留下了他们家族、发明和技艺的记录。]=],
		},
		{
			title = "当今",
			text = [=[流亡者们没有放弃。在{link:kharanos}卡拉诺斯{/link}，{link:razzle-sprysprocket}拉兹·滑链{/link}和奥齐·电环正在制造一台他们希望能让中毒{link:gnomes}侏儒{/link}复原的机器。在{link:ironforge}铁炉堡{/link}，{link:gnomeregan}诺莫瑞根{/link}的工匠们派遣勇敢的陌生人回到城中，抢救失落的知识。大工匠{link:gelbin-mekkatorque}格尔宾·梅卡托克{/link}发誓，他的人民会从占据家园的叛徒手中夺回它。]=],
		},
	},
})

